(function(){'use strict';
/* JAH The Algebra Signature generator — jahdb-algebra-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-ALGEBS-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Algebra", "desc": "Algebra is mathematics with symbols: generalizing arithmetic (2+3 = 3+2 becomes a+b = b+a), solving for unknowns, and studying structures (sets with operations). From al-Khwarizmi's al-jabr (830 CE, 'restoration') to modern abstraction.\nTwo faces: elementary (equations, functions - the language of science) and abstract (groups, rings, fields - the study of symmetry and structure). Every quantitative field speaks it.", "how": "Translate problems to symbols (define variables); manipulate by rules (same operation both sides); interpret solutions back. Progress: arithmetic → equations → functions → structures. Prove, don't just compute, at the abstract level.", "keys": ["Symbols generalize arithmetic.", "al-Khwarizmi, 830 CE (al-jabr).", "Elementary: equations; abstract: structures.", "The language of quantitative science.", "Solve, then interpret."], "reqs": ["Variables defined.", "Operations justified.", "Solution interpreted."], "stds": ["Standard notation.", "Proofs for abstract claims."], "cites": ["al-Khwarizmi. Al-Kitab al-Mukhtasar fi Hisab al-Jabr wal-Muqabala. c. 830.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Solve 2x + 3 = 11.\"\"\"\ndef solve_linear(a, b, c):\n    return (c-b)/a\nprint(f\"  x = {solve_linear(2, 3, 11)}\")\n"}, {"tier": "Foundations", "g": "Equations", "title": "Linear Equations", "desc": "ax + b = 0 → x = -b/a: one unknown, one solution (a≠0). Systems: substitution, elimination, matrices - lines intersecting (one point), parallel (none), coincident (infinite). The geometry of flatness.\nLinearity (f(a+b) = f(a)+f(b)) makes them solvable at scale: Gaussian elimination handles thousands of equations - the workhorse of scientific computing (every simulation linearizes).", "how": "Isolate the variable (inverse operations); check by substitution. For systems: eliminate (Gaussian) or substitute; classify (unique/none/infinite) geometrically. Scale with matrices for large systems.", "keys": ["ax + b = 0: one solution.", "Systems: substitution, elimination.", "0, 1, or infinite solutions.", "Linearity enables scale.", "Gaussian elimination: the workhorse."], "reqs": ["Equation in standard form.", "Solution check.", "System classification."], "stds": ["Solutions verified by substitution.", "Matrix form for systems."], "cites": ["Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002.", "Strang G. Introduction to Linear Algebra. 5th ed. Wellesley-Cambridge; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"2x2 system by elimination.\"\"\"\ndef solve2(a1,b1,c1,a2,b2,c2):\n    det = a1*b2-a2*b1\n    return ((c1*b2-c2*b1)/det, (a1*c2-a2*c1)/det)\nprint(\"  2x+y=5, x-y=1 ->\", solve2(2,1,5,1,-1,1))\n"}, {"tier": "Foundations", "g": "Equations", "title": "Quadratic Equations", "desc": "ax² + bx + c = 0: the quadratic formula x = (-b ± √(b²-4ac))/2a - completing the square generalized. Discriminant D = b²-4ac: positive (two real), zero (one), negative (complex pair).\nBabylonians solved quadratics (c. 2000 BCE); the formula unifies. Parabolas model projectiles, profit, optics - the first nonlinear equation everyone meets.", "how": "Compute discriminant first (predict root type); apply the formula; verify by substitution or factoring. Complete the square to derive it. Graph (vertex at -b/2a) for intuition.", "keys": ["Quadratic formula: the universal solver.", "Discriminant predicts root type.", "Completing the square derives it.", "Babylonian origins (~2000 BCE).", "Parabolas: projectiles, profit, optics."], "reqs": ["Standard form.", "Discriminant computed.", "Roots verified."], "stds": ["Formula stated exactly.", "Complex roots as a±bi."], "cites": ["Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002.", "Katz VJ. A History of Mathematics. 3rd ed. Pearson; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Quadratic formula.\"\"\"\nimport cmath\ndef quad(a,b,c):\n    d = b*b-4*a*c\n    return ((-b+cmath.sqrt(d))/(2*a), (-b-cmath.sqrt(d))/(2*a))\nprint(\"  x^2-5x+6=0 ->\", quad(1,-5,6))\nprint(\"  x^2+1=0 ->\", quad(1,0,1))\n"}, {"tier": "Foundations", "g": "Polynomials", "title": "Polynomials", "desc": "Sums of powers (aₙxⁿ + ... + a₀): degree n has ≤ n real roots; factor over complexes completely (Fundamental Theorem of Algebra - Gauss). Operations: add, multiply, divide (long/synthetic), factor (rational-root theorem hunts).\nGraphs: degree → end behavior; multiplicity → touch/cross. Interpolation (Lagrange) fits polynomials through points - the basis of numerical methods.", "how": "Determine degree (leading term); find rational roots (p/q theorem); factor stepwise; use multiplicity for graph shape. Interpolate with Lagrange for data fitting. Divide for remainder (Remainder theorem: P(a) = remainder at x-a).", "keys": ["Degree n: at most n real roots.", "Fundamental Theorem (Gauss).", "Factor: rational-root theorem.", "Multiplicity shapes graphs.", "Lagrange interpolation fits data."], "reqs": ["Degree identified.", "Factoring attempted.", "Roots verified."], "stds": ["Polynomials in standard form.", "Roots with multiplicity."], "cites": ["Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002.", "Gauss CF. Disquisitiones Arithmeticae. 1801."], "demo": "#!/usr/bin/env python3\n\"\"\"Rational-root candidates for 2x^3 - 3x^2 - 11x + 6.\"\"\"\ndef candidates(a0, an):\n    divs = lambda n: [d for d in range(1, abs(n)+1) if n % d == 0]\n    return sorted({p/q for p in divs(a0) for q in divs(an)} | {-p/q for p in divs(a0) for q in divs(an)})\nprint(\" \", candidates(6, 2)[:8], \"...\")\n"}, {"tier": "Foundations", "g": "Functions", "title": "Functions and Graphs", "desc": "Functions: each input → exactly one output (vertical-line test). Domain/range, composition (f∘g), inverses (reflect across y=x), transformations (shifts, stretches). The function concept (Dirichlet, 1837) unified formulas and curves.\nFamilies: linear, quadratic, polynomial, rational (asymptotes), exponential, logarithmic, trigonometric - each with signature shapes. Graphing is qualitative reasoning made visible.", "how": "Test functionhood (vertical line); find domain (exclusions: zero denominators, negative roots); compose and invert carefully (restrict domains). Sketch by transformations from parent functions. Read features (intercepts, asymptotes, extrema) off graphs.", "keys": ["One input → one output.", "Domain/range; composition; inverses.", "Dirichlet 1837: the modern concept.", "Transformations from parent functions.", "Graphs make reasoning visible."], "reqs": ["Domain stated.", "Function test passed.", "Key features identified."], "stds": ["Function notation f(x).", "Asymptotes as equations."], "cites": ["Dirichlet PGL. (Function concept, 1837).", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Function composition and inverse.\"\"\"\ndef f(x): return 2*x+3\ndef g(x): return x**2\nprint(f\"  f(g(2)) = {f(g(2))} (composition)\")\nprint(f\"  f inverse of 11 = {(11-3)/2} (undo)\")\n"}, {"tier": "Foundations", "g": "Exponents", "title": "Exponents and Logarithms", "desc": "Exponents: repeated multiplication generalized (a^m·a^n = a^{m+n}; negative/fractional/real via limits). Logarithms: inverses (log_b(xy) = log_b x + log_b y) - turning multiplication into addition (Napier 1614, slide rules, then calculators).\nNatural log (base e): calculus's choice - d/dx e^x = e^x. Log scales (decibels, pH, Richter) tame huge ranges. Exponential growth/decay: populations, radioactivity, compound interest.", "how": "Apply exponent laws (same base); convert exp↔log forms fluently. Use log properties to solve exponential equations (take logs). Choose base e for calculus, 10 for scales. Model growth/decay (N = N₀e^{kt}).", "keys": ["Laws: product, power, quotient.", "Logs invert exponentials.", "Napier 1614.", "Base e: calculus's choice.", "Log scales tame huge ranges."], "reqs": ["Base stated.", "Domain (positive arguments).", "Law justifications."], "stds": ["log_b x notation.", "ln for base e."], "cites": ["Napier J. Mirifici Logarithmorum Canonis Descriptio. 1614.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Exponential growth: doubling.\"\"\"\ndef double_time(rate):\n    import math\n    return math.log(2)/rate\nprint(f\"  7% growth doubles in {double_time(0.07):.1f} years (rule of 72: 10.3)\")\n"}, {"tier": "Foundations", "g": "Inequalities", "title": "Inequalities", "desc": "Order relations (<, >, ≤, ≥): solve like equations, but flip when multiplying/dividing by negatives. Solution sets are intervals (number-line graphs, interval notation). Compound (and/or) and absolute-value (|x-a| < d: within d of a).\nApplications: constraints (optimization), error bounds, domains. Linear programming optimizes over inequality-defined polygons - operations research's foundation.", "how": "Solve as equations, tracking sign flips; express as intervals; graph on number lines. Handle absolute value by cases (or distance interpretation). For systems, intersect regions (graph for 2D).", "keys": ["Flip on negative multiply/divide.", "Solutions are intervals.", "Absolute value: distance.", "Compound: and/or logic.", "Linear programming optimizes regions."], "reqs": ["Direction flips tracked.", "Interval notation.", "Endpoint inclusion correct."], "stds": ["Intervals as [a,b), etc.", "Number-line graphs."], "cites": ["Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002.", "Strang G. Introduction to Linear Algebra. 5th ed. Wellesley-Cambridge; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"Solve -2x + 6 < 14.\"\"\"\n# -2x < 8 -> x > -4 (flip!)\nprint(\"  -2x + 6 < 14  →  -2x < 8  →  x > -4  (flipped)\")\nprint(\"  interval: (-4, ∞)\")\n"}, {"tier": "Foundations", "g": "Sequences", "title": "Sequences and Series", "desc": "Sequences: ordered lists (arithmetic: +d each; geometric: ×r each). Series: sums - finite (formulas: n/2 first+last) and infinite (converge if terms shrink fast enough - geometric |r|<1 sums to a/(1-r)).\nSigma notation compresses sums. Applications: finance (annuities), physics (perturbation series), computer science (complexity sums). Zeno's paradox resolved by convergent series.", "how": "Classify (arithmetic/geometric/neither); find nth-term formulas. Sum finite series (formulas); test infinite convergence (geometric ratio, comparison). Use sigma notation compactly. Apply to finance (compound sums).", "keys": ["Arithmetic (+d); geometric (×r).", "Finite sums have formulas.", "Geometric converges if |r|<1.", "Sigma notation compresses.", "Zeno resolved by convergence."], "reqs": ["Sequence type.", "nth-term formula.", "Convergence test (infinite)."], "stds": ["Subscripts (a_n).", "Sigma with limits."], "cites": ["Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002.", "Katz VJ. A History of Mathematics. 3rd ed. Pearson; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Geometric series sum.\"\"\"\ndef gsum(a, r, n=None):\n    return a/(1-r) if n is None and abs(r) < 1 else a*(1-r**n)/(1-r)\nprint(f\"  1 + 1/2 + 1/4 + ... = {gsum(1, 0.5)}\")\nprint(f\"  first 10 terms: {gsum(1, 0.5, 10):.4f}\")\n"}, {"tier": "Foundations", "g": "Complex", "title": "Complex Numbers (Introduction)", "desc": "i² = -1 extends reals to a+bi: the complex plane (real × imaginary axes), modulus (distance), conjugate (mirror), arithmetic (add componentwise; multiply: FOIL with i²=-1). Cardano's formula forced them into mathematics (1545); Argand/Gauss geometrized them.\nEvery polynomial splits over ℂ (Fundamental Theorem). Euler's formula e^{iθ} = cos θ + i sin θ unites them with trigonometry - the most beautiful formula in mathematics.", "how": "Represent (a+bi, plane points); compute modulus/conjugate; do arithmetic (multiply via FOIL); divide (multiply by conjugate). Solve quadratics with negative discriminants. Preview Euler's formula for the compounded tier.", "keys": ["i² = -1; form a+bi.", "The complex plane.", "Modulus and conjugate.", "Cardano 1545; Argand/Gauss geometry.", "All polynomials split over ℂ."], "reqs": ["Real/imaginary parts.", "Plane representation.", "Conjugate for division."], "stds": ["a+bi standard form.", "Modulus |z|."], "cites": ["Cardano G. Ars Magna. 1545.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Complex arithmetic.\"\"\"\nz1, z2 = complex(3, 4), complex(1, -2)\nprint(f\"  (3+4i)(1-2i) = {z1*z2}\")\nprint(f\"  |3+4i| = {abs(z1)}\")\n"}, {"tier": "Foundations", "g": "Matrices", "title": "Matrices (Introduction)", "desc": "Rectangular arrays: add entrywise, multiply (rows × columns - noncommutative!), identity (I), inverse (A⁻¹A = I, when det≠0), transpose, determinant (2×2: ad-bc; scaling factor). Cayley (1858) founded matrix algebra.\nMatrices encode linear systems (Ax = b), transformations (rotate/scale/shear), and data. Determinant zero = singular (no inverse; system degenerate). The language of linear algebra begins here.", "how": "Add/multiply by definition (check dimensions!); compute 2×2 determinants and inverses. Solve Ax = b via inverse (small) or elimination (large). Interpret as transformations (apply to vectors). Test singularity (det = 0).", "keys": ["Multiply: rows × columns.", "Noncommutative (AB ≠ BA).", "Determinant: 2×2 ad-bc.", "Inverse exists iff det≠0.", "Cayley 1858."], "reqs": ["Dimensions compatible.", "Determinant computed.", "Inverse verified (A⁻¹A=I)."], "stds": ["Matrices as [a b; c d].", "det(A) notation."], "cites": ["Cayley A. (Matrix theory, 1858).", "Strang G. Introduction to Linear Algebra. 5th ed. Wellesley-Cambridge; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"2x2 inverse.\"\"\"\ndef inv2(a,b,c,d):\n    det = a*d-b*c\n    return [[d/det, -b/det], [-c/det, a/det]]\nprint(\"  inverse of [2 1; 1 1]:\", inv2(2,1,1,1))\n"}, {"tier": "Foundations", "g": "History", "title": "History: From al-Khwarizmi to Galois", "desc": "830 al-Khwarizmi (al-jabr); 1545 Cardano/Tartaglia (cubics); 1637 Descartes (coordinates unite algebra/geometry); 1799-1830: Abel/Ruffini (quintics unsolvable by radicals), Galois (groups decide solvability - died 1832, age 20); 1850s+: Cayley, Dedekind abstract structures.\nThe arc: solving equations → understanding solvability → studying structure itself. Noether (1915+) tied algebra to physics (symmetries ↔ conservation laws).", "how": "Trace: techniques (al-Khwarizmi) → formulas (Cardano) → impossibility (Abel/Galois) → structure (Noether). Read Galois's story as mathematics' romantic tragedy. Connect each era's question to its answer.", "keys": ["al-Khwarizmi 830: the name.", "Cardano 1545: cubics.", "Abel/Galois: quintics impossible.", "Galois: groups decide.", "Noether: symmetry ↔ conservation."], "reqs": ["Primary sources where possible.", "Timeline accuracy.", "Question-per-era framing."], "stds": ["Dates with contributions.", "Names spelled correctly."], "cites": ["Katz VJ. A History of Mathematics. 3rd ed. Pearson; 2008.", "Stewart I. Galois Theory. 4th ed. CRC; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Algebra history.\"\"\"\nfor y, e in [(830, \"al-Khwarizmi\"), (1545, \"Cardano cubics\"), (1832, \"Galois dies\"), (1915, \"Noether\")]:\n    print(f\"  {y}: {e}\")\n"}, {"tier": "Compounded", "g": "Complex", "title": "Complex Numbers: Polar Form and Euler's Formula", "desc": "Polar: z = r(cos θ + i sin θ) = re^{iθ} (Euler's formula) - multiplication becomes (r₁r₂, θ₁+θ₂): magnitudes multiply, angles add. De Moivre: (cos θ + i sin θ)ⁿ = cos nθ + i sin nθ - powers and roots geometrically.\ne^{iπ} + 1 = 0 (Euler's identity): e, i, π, 1, 0 in one equation. Roots of unity (n-th roots) form regular polygons - algebra meets geometry. Applications: AC circuits (phasors), quantum mechanics (amplitudes), signal processing (Fourier).", "how": "Convert rectangular ↔ polar (r = |z|, θ = atan2); multiply/divide in polar (easy); power via De Moivre. Find n-th roots (n polygon vertices). Apply phasors (circuits) and Fourier (signals).", "keys": ["Polar: re^{iθ}.", "Multiply: magnitudes ×, angles +.", "De Moivre: powers geometrically.", "Euler's identity: e^{iπ}+1=0.", "Roots of unity: regular polygons."], "reqs": ["Modulus and argument.", "Principal argument (-π, π].", "Geometric interpretation."], "stds": ["Polar as r∠θ or re^{iθ}.", "Arguments in radians."], "cites": ["Euler L. (Formula, 1748).", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Roots of unity (n=4).\"\"\"\nimport cmath\nfor k in range(4):\n    z = cmath.exp(2j*cmath.pi*k/4)\n    print(f\"  k={k}: {z.real:+.0f}{z.imag:+.0f}i\")\n"}, {"tier": "Compounded", "g": "Linear Algebra", "title": "Systems of Linear Equations (Matrix Methods)", "desc": "Ax = b: Gaussian elimination (row operations → echelon), Gauss-Jordan (→ reduced), LU decomposition (factor once, solve many), determinants (Cramer's rule - theoretical). Rank reveals: rank(A) vs rank([A|b]) decides consistency.\nHomogeneous (Ax=0): always has trivial; nontrivial iff singular - null space is the solution set. Least squares (AᵀA x̂ = Aᵀb) solves inconsistent systems approximately - regression's engine.", "how": "Row-reduce (track operations); read rank and consistency; back-substitute. Factor LU for repeated b's. For overdetermined: least squares (normal equations). Check conditioning (ill-conditioned systems amplify error).", "keys": ["Elimination → echelon form.", "Rank decides consistency.", "Homogeneous: null space.", "Least squares: best approximate.", "LU: factor once, solve many."], "reqs": ["Augmented matrix.", "Rank computation.", "Consistency check."], "stds": ["Echelon forms exact.", "Solutions verified."], "cites": ["Strang G. Introduction to Linear Algebra. 5th ed. Wellesley-Cambridge; 2016.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Solve via Gaussian elimination (2x2).\"\"\"\ndef gauss(a1,b1,c1,a2,b2,c2):\n    m = a2/a1\n    b2n, c2n = b2-m*b1, c2-m*c1\n    y = c2n/b2n\n    return ((c1-b1*y)/a1, y)\nprint(\"  2x+y=5, x+3y=6 ->\", tuple(round(v,3) for v in gauss(2,1,5,1,3,6)))\n"}, {"tier": "Compounded", "g": "Linear Algebra", "title": "Vector Spaces", "desc": "Vector spaces: sets with addition + scalar multiplication satisfying 8 axioms (ℝⁿ, polynomials, functions, matrices). Subspaces, span, linear independence, basis (minimal spanning set), dimension (basis size - well-defined).\nThe abstraction unifies: polynomials of degree ≤ n behave like ℝⁿ⁺¹. Linear transformations (matrices) map between spaces; kernel/image measure information loss/preservation (rank-nullity: dim ker + dim im = dim domain).", "how": "Verify axioms for new examples; test independence (only trivial combination = 0); find bases (reduce spanning sets); compute dimension. Represent transformations as matrices (relative to bases); apply rank-nullity.", "keys": ["8 axioms define vector spaces.", "Basis: minimal spanning set.", "Dimension: basis size.", "Rank-nullity theorem.", "Polynomials ≅ ℝⁿ⁺¹ (as spaces)."], "reqs": ["Axiom verification.", "Independence test.", "Basis/dimension."], "stds": ["Bases as sets.", "Dimension as integer."], "cites": ["Strang G. Introduction to Linear Algebra. 5th ed. Wellesley-Cambridge; 2016.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Dimension examples.\"\"\"\nfor space, dim in [(\"R^3\", 3), (\"P_2 (quadratics)\", 3), (\"M_2x2\", 4), (\"solutions of y2+y=0\", 2)]:\n    print(f\"  {space:22s}: dim {dim}\")\n"}, {"tier": "Compounded", "g": "Linear Algebra", "title": "Eigenvalues and Eigenvectors", "desc": "Av = λv: vectors that only scale under A - the transformation's natural axes. Characteristic polynomial det(A-λI) = 0 gives eigenvalues; solve (A-λI)v = 0 for eigenvectors. Diagonalization (A = PDP⁻¹) decouples systems.\nApplications: stability (differential equations - negative eigenvalues decay), PCA (data's principal axes), quantum mechanics (observables' eigenvalues), PageRank (dominant eigenvector of the web).", "how": "Compute characteristic polynomial; find eigenvalues (roots); solve for eigenvectors (null spaces). Diagonalize when possible (n independent eigenvectors); apply (powers: A^k = PD^kP⁻¹). Interpret: stability, principal axes, steady states.", "keys": ["Av = λv: natural axes.", "det(A-λI) = 0 gives eigenvalues.", "Diagonalization decouples.", "Stability: sign of eigenvalues.", "PCA, PageRank, quantum: applications."], "reqs": ["Characteristic polynomial.", "Eigenvector verification.", "Diagonalizability check."], "stds": ["Eigenvalues with multiplicity.", "Eigenvectors normalized where apt."], "cites": ["Strang G. Introduction to Linear Algebra. 5th ed. Wellesley-Cambridge; 2016.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Eigenvalues of 2x2.\"\"\"\ndef eigen2(a,b,c,d):\n    import cmath\n    tr, det = a+d, a*d-b*c\n    disc = cmath.sqrt(tr*tr-4*det)\n    return ((tr+disc)/2, (tr-disc)/2)\nprint(\"  [4 1; 2 3]:\", eigen2(4,1,2,3))\n"}, {"tier": "Compounded", "g": "Polynomials", "title": "Factoring and Root-Finding", "desc": "Factoring strategies: GCF, grouping, quadratics (formula/factoring), sum/difference of cubes, rational-root theorem + synthetic division, special forms. Complete over ℂ always (Fundamental Theorem).\nNumerical root-finding: bisection (robust, slow), Newton (fast, needs derivative/good guess), secant. Multiplicity affects convergence. Galois theory explains why degree ≥ 5 has no general radical formula.", "how": "Try exact factoring (rational roots first); fall back to numerical (bracket then Newton). Handle multiplicity (deflate found roots). For degree ≥ 5, expect numerical answers. Verify roots (substitute; residuals).", "keys": ["Rational roots first.", "Synthetic division deflates.", "Bisection robust; Newton fast.", "Degree ≥ 5: no radical formula.", "Verify by substitution."], "reqs": ["Factoring attempt.", "Numerical method + bracket.", "Verification."], "stds": ["Roots with multiplicity.", "Residuals reported."], "cites": ["Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002.", "Stewart I. Galois Theory. 4th ed. CRC; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Newton method for x^2 - 2.\"\"\"\ndef newton(x):\n    return x-(x*x-2)/(2*x)\nx = 1.0\nfor _ in range(5):\n    x = newton(x)\nprint(f\"  sqrt(2) ≈ {x:.10f}\")\n"}, {"tier": "Compounded", "g": "Polynomials", "title": "The Binomial Theorem", "desc": "(a+b)ⁿ = Σ C(n,k) a^{n-k} b^k: Pascal's triangle gives coefficients (each = sum of two above); combinatorial proof (choose k b's from n factors). Newton generalized to real exponents (infinite series).\nApplications: probability (binomial distribution), approximations ((1+x)ⁿ ≈ 1+nx), combinatorial identities (sum of row = 2ⁿ). The bridge between algebra and combinatorics.", "how": "Expand via coefficients (Pascal/combinations); verify small cases by multiplication. Apply to probability (binomial terms); approximate ((1+x)ⁿ series). Prove identities by coefficient comparison.", "keys": ["Coefficients: C(n,k).", "Pascal's triangle generates.", "Combinatorial proof.", "Newton: real exponents.", "Probability + approximation uses."], "reqs": ["n specified.", "Coefficients computed.", "Expansion verified."], "stds": ["C(n,k) notation.", "Summation form."], "cites": ["Newton I. (Generalized binomial, 1676).", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Binomial expansion of (a+b)^4.\"\"\"\nimport math\nn = 4\nterms = [f\"{math.comb(n,k)}a^{n-k}b^{k}\" for k in range(n+1)]\nprint(\"  \" + \" + \".join(terms))\n"}, {"tier": "Compounded", "g": "Structures", "title": "Groups: First Look", "desc": "Groups: sets with one operation satisfying closure, associativity, identity, inverses - symmetry's algebraic form. Examples: integers under + (ℤ), non-zero rationals under ×, symmetries of shapes (D₄ of the square), permutations (Sₙ).\nSubgroups, cosets, Lagrange's theorem (|H| divides |G| - finite groups), homomorphisms (structure-preserving maps). Galois used groups to decide equation solvability - symmetry governs solutions.", "how": "Verify group axioms for examples; find subgroups (closure test); compute cosets; apply Lagrange (possible subgroup orders). Build homomorphisms (check operation preservation); find kernels/images.", "keys": ["4 axioms: closure, assoc, identity, inverses.", "Symmetry's algebraic form.", "Lagrange: |H| divides |G|.", "Subgroups, cosets, homomorphisms.", "Galois: groups decide solvability."], "reqs": ["Operation + set specified.", "Axiom verification.", "Examples (≥2)."], "stds": ["Groups as (G, *).", "Orders as |G|."], "cites": ["Galois É. (1832).", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Lagrange: subgroup orders divide group order.\"\"\"\ndef divisors(n):\n    return [d for d in range(1, n+1) if n % d == 0]\nprint(\"  |G|=12 -> possible |H|:\", divisors(12))\n"}, {"tier": "Compounded", "g": "Structures", "title": "Rings and Fields: First Look", "desc": "Rings: two operations (+, ×) - abelian group under +, associative × with distributivity (ℤ, polynomials, matrices). Fields: every non-zero element has a multiplicative inverse (ℚ, ℝ, ℂ, finite fields F_p).\nIdeals (ring's subgroups for ×), quotient rings, integral domains (no zero divisors), polynomial rings F[x]. Fields are where linear algebra and equation-solving work smoothly - division always available.", "how": "Verify ring/field axioms; distinguish (ℤ ring not field; ℚ field). Find ideals (kernels of homomorphisms); form quotients (ℤ/nℤ). Test zero divisors (integral domain?). Work in F_p (modular arithmetic) for finite fields.", "keys": ["Rings: + and × with distributivity.", "Fields: division by non-zero.", "Ideals → quotient rings.", "ℤ/nℤ: the modular ring.", "F_p: finite fields."], "reqs": ["Axiom verification.", "Ring vs field determination.", "Ideal identification."], "stds": ["Rings as (R, +, ×).", "F_p notation."], "cites": ["Dedekind R. (Ideals, 1871).", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Field check: inverses mod 7.\"\"\"\ndef inv(a, p):\n    return next(x for x in range(p) if (a*x) % p == 1)\nprint(\"  inverses mod 7:\", {a: inv(a, 7) for a in range(1, 7)})\n"}, {"tier": "Compounded", "g": "Number Theory Link", "title": "Modular Arithmetic", "desc": "a ≡ b (mod n): same remainder - arithmetic on a finite clock. Operations well-defined on classes; ℤ/nℤ is a ring, a field when n prime. Inverses via extended Euclidean algorithm.\nApplications: cryptography (RSA lives in modular arithmetic), checksums (ISBN), calendars, computer science (hashing). Fermat's little theorem (a^{p-1} ≡ 1) powers primality tests.", "how": "Reduce mod n fluently; add/multiply classes; find inverses (extended Euclid); solve congruences (linear: ax ≡ b). Apply Fermat/Euler theorems for powers. Use in RSA setup (see number-theory DB).", "keys": ["Congruence: same remainder.", "ℤ/nℤ ring; field iff prime.", "Extended Euclid finds inverses.", "Fermat's little theorem.", "RSA lives here."], "reqs": ["Modulus stated.", "Class representatives.", "Inverse verification."], "stds": ["a ≡ b (mod n).", "Fermat: a^{p-1} ≡ 1 (mod p)."], "cites": ["Gauss CF. Disquisitiones Arithmeticae. 1801.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Fast modular exponentiation.\"\"\"\ndef modpow(a, e, n):\n    r = 1\n    while e:\n        if e & 1: r = r*a % n\n        a, e = a*a % n, e >> 1\n    return r\nprint(f\"  7^100 mod 13 = {modpow(7, 100, 13)} (Fermat: 7^12≡1)\")\n"}, {"tier": "Compounded", "g": "Applications", "title": "Linear Programming", "desc": "Optimize linear objectives over inequality-defined polygons: maximize cᵀx subject to Ax ≤ b. Fundamental theorem: optima at vertices - simplex method (Dantzig 1947) walks vertex-to-vertex; interior-point methods (Karmarkar 1984) cut through.\nApplications: resource allocation, diet problems, transportation, scheduling - operations research's core. Duality (every LP has a dual; strong duality: equal optima) gives economic interpretations (shadow prices).", "how": "Formulate (objective + constraints); graph 2D cases (corner-point theorem); run simplex or software for large. Interpret dual (shadow prices). Check feasibility/boundedness first.", "keys": ["Optimize linear over polygons.", "Optima at vertices.", "Simplex (1947); interior-point (1984).", "Duality: shadow prices.", "Allocation, diet, transport."], "reqs": ["Objective + constraints.", "Feasibility check.", "Vertex enumeration (2D)."], "stds": ["Standard form stated.", "Dual formulated."], "cites": ["Dantzig GB. (Simplex, 1947).", "Strang G. Introduction to Linear Algebra. 5th ed. Wellesley-Cambridge; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"Corner-point: max 3x+2y, x+y<=4, x,y>=0.\"\"\"\ncorners = [(0,0),(4,0),(0,4)]\nbest = max(corners, key=lambda p: 3*p[0]+2*p[1])\nprint(f\"  optimum at {best}: value {3*best[0]+2*best[1]}\")\n"}, {"tier": "Compounded", "g": "Applications", "title": "Algebra in Cryptography (Introduction)", "desc": "Cryptography is applied algebra: RSA (modular exponentiation, Euler's theorem - security from factoring difficulty), Diffie-Hellman (discrete logs in cyclic groups), elliptic curves (group law on curves - same security, smaller keys).\nSymmetric (AES: field operations in GF(2⁸)) vs asymmetric (number-theoretic hardness). Hash functions, signatures, zero-knowledge - all algebraic structures in service of secrecy. (Full treatment: number-theory DB.)", "how": "Implement RSA toy (primes → keys → encrypt/decrypt); run Diffie-Hellman key exchange (small group); add in GF(2⁸) for AES flavor. Emphasize: toy sizes only - real security needs 2048+ bits and vetted libraries.", "keys": ["RSA: factoring hardness.", "Diffie-Hellman: discrete logs.", "Elliptic curves: smaller keys.", "AES: field GF(2⁸).", "Toy sizes only - use vetted libraries."], "reqs": ["Group/field specified.", "Hardness assumption.", "Toy-size disclaimer."], "stds": ["Keys in bits.", "Never roll your own crypto."], "cites": ["Rivest R et al. Commun ACM 1978;21:120-126.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Tiny RSA (toy only!).\"\"\"\np, q = 61, 53\nn, phi = p*q, (p-1)*(q-1)\ne = 17\nd = next(d for d in range(phi) if (e*d) % phi == 1)\nm, c = 42, pow(42, e, n)\nprint(f\"  encrypt {m} -> {c}; decrypt -> {pow(c, d, n)} (keys: e={e}, d={d}, n={n})\")\n"}, {"tier": "Compounded", "g": "Logic", "title": "Boolean Algebra", "desc": "Algebra of truth: AND, OR, NOT with laws (De Morgan, distributivity, absorption) - Boole 1847. Truth tables decide; normal forms (CNF/DNF) standardize. Shannon (1938) mapped it to circuits - the mathematics of computers.\nLogic gates (NAND universal), simplification (Karnaugh maps), SAT solving. Every program's conditionals are Boolean algebra executing.", "how": "Evaluate via truth tables; simplify with laws (De Morgan!); convert to normal forms. Design gate circuits (NAND-only); minimize (K-maps). Verify equivalences by table.", "keys": ["AND, OR, NOT: the operators.", "De Morgan's laws.", "Boole 1847; Shannon 1938.", "NAND is universal.", "Truth tables decide."], "reqs": ["Variables/propositions.", "Truth-table verification.", "Simplification shown."], "stds": ["∧, ∨, ¬ or AND/OR/NOT.", "Tables complete."], "cites": ["Boole G. The Laws of Thought. 1854.", "Shannon CE. (Circuits, 1938)."], "demo": "#!/usr/bin/env python3\n\"\"\"De Morgan verification.\"\"\"\nfor a in (False, True):\n    for b in (False, True):\n        assert (not (a and b)) == ((not a) or (not b))\nprint(\"  NOT(A AND B) = (NOT A) OR (NOT B): verified all cases\")\n"}, {"tier": "Advanced", "g": "Groups", "title": "Group Theory: Subgroups, Cosets, Lagrange", "desc": "Structure of groups: subgroups (closure test), cosets (partition the group - all same size), Lagrange's theorem (|H| | |G| - subgroup orders divide), normal subgroups (gHg⁻¹ = H - kernels of homomorphisms), quotient groups G/N.\nClassification: cyclic groups (one generator - ℤ/nℤ), symmetric Sₙ (all permutations), dihedral Dₙ (polygon symmetries), simple groups (no normal subgroups - the finite simple classification: 26 sporadics + families, 10,000+ pages).", "how": "Test subgroups (finite: closure suffices); partition into cosets; apply Lagrange (rule out orders). Check normality (conjugate test); form quotients. Classify small groups (order p², pq).", "keys": ["Cosets partition; equal size.", "Lagrange: orders divide.", "Normal: kernels; quotients G/N.", "Cyclic, symmetric, dihedral families.", "Simple groups classified."], "reqs": ["Group presentation.", "Subgroup test.", "Normality check."], "stds": ["Orders as |G|.", "Cosets as gH."], "cites": ["Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002.", "Rotman J. An Introduction to the Theory of Groups. 4th ed. Springer; 1995."], "demo": "#!/usr/bin/env python3\n\"\"\"Cosets of evens in Z_12.\"\"\"\nG = list(range(12))\nH = [0, 2, 4, 6, 8, 10]\ncosets = sorted({tuple(sorted((g+h) % 12 for h in H)) for g in G})\nprint(f\"  {len(cosets)} cosets of size {len(H)}: index {len(G)//len(H)}\")\n"}, {"tier": "Advanced", "g": "Groups", "title": "Group Actions and Symmetry", "desc": "Groups act on sets (rotations move polygon vertices): orbits (reachable points), stabilizers (fixing subgroup), orbit-stabilizer theorem (|orbit| × |stab| = |G|) - counting via symmetry. Burnside's lemma counts orbits (distinct colorings).\nApplications: counting isomers (chemistry), Rubik's cube (group of 43 quintillion), crystallography (230 space groups), physics (Noether: symmetries ↔ conservation laws). Symmetry is a group action - the universe's deepest pattern.", "how": "Define the action (homomorphism to permutations); compute orbits/stabilizers; apply orbit-stabilizer for counts. Use Burnside for inequivalent configurations. Identify symmetry groups (molecules, tilings, cubes).", "keys": ["Actions: groups move sets.", "Orbit-stabilizer: |orb|×|stab|=|G|.", "Burnside counts orbits.", "Rubik's: 43 quintillion.", "Noether: symmetry ↔ conservation."], "reqs": ["Action defined.", "Orbits computed.", "Fixed points (Burnside)."], "stds": ["Actions as G × X → X.", "Cycle index where apt."], "cites": ["Noether E. (1918, symmetry theorem).", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Burnside: 2-colorings of square under rotation.\"\"\"\n# rotations fix: 0°:16, 90°:2, 180°:4, 270°:2 -> (16+2+4+2)/4\nprint(f\"  distinct necklaces: {(16+2+4+2)//4}\")\n"}, {"tier": "Advanced", "g": "Rings", "title": "Ring Theory: Ideals and Quotients", "desc": "Ideals: subgroups absorbing multiplication - kernels of ring homomorphisms, the key substructure. Quotient rings R/I (ℤ/nℤ = ℤ/(n)); prime ideals (R/P an integral domain), maximal ideals (R/M a field) - algebraic geometry reads points as maximal ideals.\nThe hierarchy: Euclidean domains (division algorithm) → PIDs (every ideal principal: ℤ, F[x]) → UFDs (unique factorization). Each strictly stronger: ℤ[√-5] is not a UFD (6 = 2·3 = (1+√-5)(1-√-5)).", "how": "Test ideal-hood (absorption: r·a ∈ I); form quotients (coset multiplication well-defined iff ideal); identify prime/maximal via quotients. Classify domains with counterexamples. Factor in UFDs; exhibit non-uniqueness where it fails.", "keys": ["Ideals absorb multiplication.", "Quotients R/I.", "Prime → domain; maximal → field.", "Euclidean → PID → UFD.", "ℤ[√-5]: factorization fails."], "reqs": ["Ideal verification.", "Quotient construction.", "Domain classification."], "stds": ["Ideals as (a) or (a,b).", "Quotients R/I."], "cites": ["Dedekind R. (Ideals, 1871).", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Zero divisors in Z_6 (not a domain).\"\"\"\npairs = [(a,b) for a in range(6) for b in range(6) if a*b % 6 == 0 and a != 0 and b != 0]\nprint(f\"  zero-divisor pairs in Z_6: {pairs[:4]}...\")\n"}, {"tier": "Advanced", "g": "Fields", "title": "Field Theory and Extensions", "desc": "Fields: ℚ, ℝ, ℂ, finite F_q. Extensions K/F (adjoining roots: ℚ(√2)); degree [K:F] (dimension as vector space); algebraic (satisfies polynomial) vs transcendental (π, e - Lindemann 1882). Splitting fields (all roots adjoined); algebraic closure (ℂ closes ℚ).\nFinite fields F_{pⁿ}: exist for prime powers, unique up to isomorphism - Reed-Solomon codes, AES's GF(2⁸), elliptic-curve cryptography all live here. Characteristic p arithmetic (freshman's dream (a+b)^p = a^p + b^p actually holds).", "how": "Compute extension degrees (tower law: [K:F] = [K:E][E:F]); find minimal polynomials; test algebraicity. Construct F_{pⁿ} (irreducible polynomial mod p); do arithmetic (AES's field as example). Apply to codes/crypto.", "keys": ["Extensions adjoin roots.", "Degree = vector-space dimension.", "Algebraic vs transcendental.", "F_{pⁿ}: prime powers only.", "Characteristic p: (a+b)^p = a^p+b^p."], "reqs": ["Base field stated.", "Minimal polynomial.", "Degree computation."], "stds": ["Extensions K/F.", "Degrees [K:F]."], "cites": ["Galois É. (1832).", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Freshman dream mod 5.\"\"\"\nfor a in range(5):\n    for b in range(5):\n        assert pow(a+b, 5, 5) == (pow(a, 5, 5)+pow(b, 5, 5)) % 5\nprint(\"  (a+b)^5 = a^5+b^5 mod 5: verified all 25 cases\")\n"}, {"tier": "Advanced", "g": "Fields", "title": "Galois Theory", "desc": "Galois's insight: polynomial solvability ↔ its Galois group's structure (solvable groups ↔ solvable by radicals). The fundamental correspondence: intermediate fields ↔ subgroups - a perfect dictionary between fields and groups.\nQuintics: S₅ not solvable → no general radical formula (Abel-Ruffini). Constructibility: regular n-gons constructible iff φ(n) is a power of 2 (Gauss, 17-gon at 19). The most beautiful theory in algebra - symmetry deciding solvability.", "how": "Compute Galois groups (small cases: discriminants, resolvents); test solvability (composition factors cyclic of prime order). Apply correspondence (subgroups ↔ intermediate fields). Prove impossibilities (angle trisection, cube doubling).", "keys": ["Solvability ↔ group structure.", "Fields ↔ subgroups (correspondence).", "S₅: quintics unsolvable.", "Galois, 1832 (age 20).", "Constructibility via φ(n)."], "reqs": ["Polynomial + splitting field.", "Galois group.", "Correspondence pairs."], "stds": ["Gal(K/F) notation.", "Groups named (Sₙ, Aₙ, Dₙ)."], "cites": ["Galois É. (1832).", "Stewart I. Galois Theory. 4th ed. CRC; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Solvable orders check.\"\"\"\ndef divisors(n):\n    return [d for d in range(1, n+1) if n % d == 0]\nprint(\"  S_3 order 6: subgroups of orders\", divisors(6), \"(solvable -> cubics solvable)\")\nprint(\"  S_5 order 120: simple A_5 blocks solvability\")\n"}, {"tier": "Advanced", "g": "Linear Algebra", "title": "Linear Algebra: Advanced Topics", "desc": "Beyond basics: canonical forms (Jordan - eigenvalues + block sizes classify; rational canonical), inner products (Gram-Schmidt, orthogonality, least squares geometry), spectral theorem (symmetric/Hermitian diagonalize orthogonally - quantum mechanics' foundation), SVD (A = UΣVᵀ - data science's workhorse: PCA, compression).\nDual spaces, tensors (multilinear algebra - general relativity's language), modules over PIDs (unifying vector spaces and abelian groups). Linear algebra is the most applicable abstract subject - everything linearizes.", "how": "Compute Jordan forms (generalized eigenvectors); orthogonalize (Gram-Schmidt); diagonalize symmetric (spectral). Apply SVD (low-rank approximation); work with tensors (index notation). Use modules to unify.", "keys": ["Jordan form classifies.", "Spectral: symmetric diagonalizes.", "SVD: A = UΣVᵀ.", "Inner products geometrize.", "Tensors: multilinear maps."], "reqs": ["Canonical form target.", "Inner product specified.", "Application context."], "stds": ["Jordan blocks J_k(λ).", "SVD dimensions stated."], "cites": ["Strang G. Introduction to Linear Algebra. 5th ed. Wellesley-Cambridge; 2016.", "Axler S. Linear Algebra Done Right. 3rd ed. Springer; 2014."], "demo": "#!/usr/bin/env python3\n\"\"\"SVD low-rank idea.\"\"\"\nprint(\"  A = U Σ Vᵀ; keep top k singular values\")\nprint(\"  image compression: k=50 keeps ~95% (typical photo)\")\n"}, {"tier": "Advanced", "g": "Polynomials", "title": "Polynomial Rings and Algebraic Geometry (Introduction)", "desc": "F[x₁,...,xₙ]: ideals are solution sets (varieties) - Hilbert's Nullstellenssatz ties ideals to geometry (radical ideals ↔ varieties over algebraically closed fields). Gröbner bases (Buchberger 1965) compute with ideals: solving, elimination, ideal membership - algebra made algorithmic.\nApplications: robotics (configuration spaces), optimization (polynomial systems), cryptography (multivariate), CAD. The bridge from algebra to geometry - modern mathematics' central highway.", "how": "Compute Gröbner bases (lex order for elimination); solve systems (triangularize); test ideal membership (remainder zero?). Interpret geometrically (varieties). Use CAS (Singular, Macaulay2) for serious computation.", "keys": ["Ideals ↔ varieties (Nullstellenssatz).", "Gröbner bases compute.", "Buchberger 1965.", "Elimination solves systems.", "Robotics, crypto applications."], "reqs": ["Polynomial ring.", "Monomial order.", "Geometric interpretation."], "stds": ["Monomial orders stated.", "Ideals as (f₁,...,f_k)."], "cites": ["Cox D et al. Ideals, Varieties, and Algorithms. 4th ed. Springer; 2015.", "Hilbert D. (Nullstellenssatz, 1893)."], "demo": "#!/usr/bin/env python3\n\"\"\"Elimination idea.\"\"\"\nprint(\"  system: x^2+y^2=1, x=y\")\nprint(\"  Groebner (lex x>y) -> triangular: y^2=1/2, x=y\")\nprint(\"  solutions: (±1/√2, ±1/√2)\")\n"}, {"tier": "Advanced", "g": "Number Theory Link", "title": "Algebraic Number Theory (Introduction)", "desc": "Numbers as algebra: rings of integers (ℤ[√-5], ℤ[i]), ideals restore unique factorization (Dedekind: ideals factor uniquely even when elements don't), class groups measure the failure (class number 1 = UFD).\nFermat's Last Theorem: Kummer's ideal theory for cyclotomic fields → Wiles's 1995 proof (modularity). Ramification, splitting of primes - arithmetic as geometry. The deepest link between algebra and numbers.", "how": "Work in rings of integers (norms: N(a+bi) = a²+b²); factor ideals not elements; compute class numbers (small cases). Trace FLT's history (Kummer → Wiles). Use Minkowski bounds for class groups.", "keys": ["Ideals factor uniquely.", "Class group measures failure.", "ℤ[i]: Gaussian integers (UFD).", "Kummer → Wiles (FLT 1995).", "Norms enable arithmetic."], "reqs": ["Ring of integers.", "Norm function.", "Ideal factorization."], "stds": ["Norms N(α).", "Class numbers h."], "cites": ["Wiles A. Ann Math 1995;141:443-551.", "Marcus DA. Number Fields. Springer; 1977."], "demo": "#!/usr/bin/env python3\n\"\"\"Gaussian integer norm multiplicativity.\"\"\"\ndef N(z):\n    return z.real**2+z.imag**2\na, b = complex(1,2), complex(3,1)\nprint(f\"  N({a})·N({b}) = {N(a)*N(b):.0f} = N({a*b}) = {N(a*b):.0f}\")\n"}, {"tier": "Advanced", "g": "Homological", "title": "Homological Algebra (Introduction)", "desc": "Algebra of holes: chain complexes (...→C₂→C₁→C₀), homology (ker/im - cycles modulo boundaries), exact sequences (im = ker at each step - the fundamental diagnostic). Derived from topology (simplicial homology) but purely algebraic.\nApplications: algebraic topology (holes in spaces), algebraic geometry (sheaf cohomology), representation theory (Ext/Tor). The language of modern pure mathematics - obstructions as algebra.", "how": "Build chain complexes (boundary maps with d²=0); compute homology (Smith normal form for finitely generated); chase diagrams (exact sequences). Interpret: Hₙ counts n-dimensional holes. Learn by topological examples first.", "keys": ["Complexes: d² = 0.", "Homology: cycles/boundaries.", "Exact: im = ker.", "Counts holes algebraically.", "Modern math's language."], "reqs": ["Complex defined.", "Boundary maps.", "Topological motivation."], "stds": ["Hₙ notation.", "Exact sequences with 0s."], "cites": ["Weibel CA. An Introduction to Homological Algebra. Cambridge; 1994.", "Fraleigh JB. A First Course in Abstract Algebra. 7th ed. Addison-Wesley; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"Euler characteristic from homology ranks.\"\"\"\n# torus: b0=1, b1=2, b2=1 -> chi = 0\nbetti = [1, 2, 1]\nchi = sum((-1)**i*b for i, b in enumerate(betti))\nprint(f\"  torus Betti {betti}: χ = {chi}\")\n"}, {"tier": "Advanced", "g": "Applications", "title": "Algebra in Coding Theory", "desc": "Error correction is algebra: linear codes (subspaces of F_qⁿ; generator/parity-check matrices), Hamming codes (perfect single-error correction), Reed-Solomon (polynomials over finite fields - CDs, QR codes, deep-space), LDPC/turbo (near Shannon limit).\nSyndrome decoding (cosets!), cyclic codes (ideals in F[x]/(xⁿ-1)), Goppa codes. Every digital transmission - from CDs to 5G to Voyager - rides on algebraic coding.", "how": "Construct generator/parity-check matrices; encode (multiply); decode (syndrome lookup). Build Reed-Solomon (evaluate polynomials); test burst-error correction. Compute code parameters [n,k,d].", "keys": ["Linear codes: subspaces.", "Hamming: perfect codes.", "Reed-Solomon: polynomials (CDs, QR).", "Syndrome = coset decoding.", "Near-Shannon: LDPC/turbo."], "reqs": ["Field F_q.", "Parameters [n,k,d].", "Channel model."], "stds": ["[n,k,d] notation.", "Syndrome tables."], "cites": ["Hamming RW. Bell Syst Tech J 1950;29:147-160.", "MacWilliams FJ, Sloane NJA. The Theory of Error-Correcting Codes. North-Holland; 1977."], "demo": "#!/usr/bin/env python3\n\"\"\"Hamming(7,4) parity check idea.\"\"\"\nprint(\"  4 data bits + 3 parity bits = 7-bit codeword\")\nprint(\"  syndrome (3 bits) locates single error -> correct it\")\n"}, {"tier": "Advanced", "g": "Frontiers", "title": "Computational Algebra", "desc": "Algorithms for algebra: Gröbner bases (Buchberger; F4/F5), integer factorization (number field sieve - RSA's adversary), discrete logs, polynomial gcd, lattice reduction (LLL - breaks knapsacks, finds relations).\nSystems: SageMath, Macaulay2, Singular, GAP (groups), PARI/GP (numbers). Complexity: Gröbner doubly-exponential worst-case; practical on structured problems. Computer algebra makes the abstract concrete - experiment, then prove.", "how": "Use CAS for exploration (Sage/GAP/Singular); implement Buchberger (toy); test conjectures computationally before proving. Mind complexity (worst-case vs practical). Verify symbolically, not just numerically.", "keys": ["Gröbner: Buchberger/F4/F5.", "LLL: lattice reduction.", "NFS: factors RSA moduli.", "Sage, GAP, Singular, Macaulay2.", "Experiment, then prove."], "reqs": ["CAS/system named.", "Algorithm + complexity.", "Verification method."], "stds": ["Complexities stated.", "Timings where relevant."], "cites": ["Buchberger B. (1965, Gröbner bases).", "Cox D et al. Ideals, Varieties, and Algorithms. 4th ed. Springer; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Polynomial GCD via Euclid.\"\"\"\ndef pgcd(a, b):\n    return a if b == 0 else pgcd(b, a % b)\nprint(f\"  gcd(48, 18) = {pgcd(48, 18)} (Euclid: the original algorithm)\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-ALGEBS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||true;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-ALGEBS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-algebra-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('algebra-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
